  need(axis === "x" || axis === "z", `doorPair: axis ${axis} (x|z)`);
  const [dx, dz] = axis === "x" ? [1, 0] : [0, 1];
  door(g, x, z, facing, "left", true);
  door(g, x + dx, z + dz, facing, "right", true);
}

